+    if (stfi && !sfi) {
+        expert_add_info(pinfo, flexray_frame_tree, &ei_flexray_stfi_flag);
+        call_subdissector = false;
+    }
+
+    proto_tree_add_item_ret_uint16(flexray_frame_tree, hf_flexray_fid, tvb, 0, 2, ENC_BIG_ENDIAN, &flexray_id);
